/// Band Cholesky solve; `kd` is the Hessian half-bandwidth in scalar
/// parameters. Returns the status code (>= 0: LmStatus; -1: solve
/// failure; -2: panic). Failure text via graph_last_error;
/// `out.detail` as in the other solves.
#[no_mangle]
pub unsafe extern "C" fn graph_solve_band(
    h: *mut GraphHandle,
    kd: u32,
    cfg: *const CLmConfig,
    out: *mut CLmResult,
) -> i32 {
    let hh = &mut *h;
    let c = (*cfg).to_config();
    zero_result(out);
    match catch_unwind(AssertUnwindSafe(|| {
        let mut x0 = Vec::new();
        hh.model.serialize64(&mut x0);
        arael::simple_lm::solve_band(&x0, kd as usize, &mut hh.model, &c).map(|r| {
            hh.model.deserialize64(&r.x);
            r
        })
    })) {
        Ok(Ok(r)) => {
            let code = fill_result(out, &r);
            (*out).detail = boxed(r);
            set_text(hh, "");
            code
        }
        Ok(Err(f)) => {
            set_text(hh, &f.to_string());
            if let Some(p) = f.partial {
                fill_result(out, &p);
                (*out).status = -1;
                (*out).detail = boxed(*p);
            }
            -1
        }
        Err(p) => {
            let msg = panic_text(p);
            set_text(hh, &msg);
            (*out).status = -2;
            -2
        }
    }
}

/// Total cost at the current parameter values (evaluated at the
/// model's precision, returned as f64).
#[no_mangle]
pub unsafe extern "C" fn graph_cost(h: *mut GraphHandle) -> f64 {
    let m = &mut (*h).model;
    let mut params = Vec::new();
    m.serialize64(&mut params);
    m.calc_cost(&params)
}

/// mode: 0 = PerQuery, 1 = AllMarginals, 2 = TriDiagonal. Returns 0,
/// -1 (error, text via graph_last_error), -2 (panic).
#[no_mangle]
pub unsafe extern "C" fn graph_assemble_covariance(h: *mut GraphHandle, mode: u32) -> i32 {
    let hh = &mut *h;
    let m = match mode {
        0 => CovMode::PerQuery,
        2 => CovMode::TriDiagonal,
        _ => CovMode::AllMarginals,
    };
    hh.cov = None;
    match catch_unwind(AssertUnwindSafe(|| hh.model.assemble_covariance(m))) {
        Ok(Ok(c)) => {
            hh.cov = Some(c);
            set_text(hh, "");
            0
        }
        Ok(Err(e)) => {
            set_text(hh, &format!("{}", e));
            -1
        }
        Err(p) => {
            let msg = panic_text(p);
            set_text(hh, &msg);
            -2
        }
    }
}

/// Row-major dim x dim marginal covariance (f64) of one `Pose2`; returns
/// dim, or -1 (error) / -2 (panic) / -3 (no assembly or buffer too
/// small), text via graph_last_error.
#[no_mangle]
pub unsafe extern "C" fn graph_pose2_marginal_cov(
    h: *mut GraphHandle,
    p: *const Pose2,
    out: *mut f64,
    cap: u32,
) -> i32 {
    let hh = &mut *h;
    let Some(cov) = hh.cov.as_ref() else {
        set_text(hh, "marginal_cov: assemble_covariance was not called");
        return -3;
    };
    match catch_unwind(AssertUnwindSafe(|| cov.marginal_cov(&*p))) {
        Ok(Ok(m)) => {
            let dim = m.nrows();
            if (dim * dim) as u32 > cap {
                set_text(hh, "marginal_cov: buffer too small");
                return -3;
            }
            for r in 0..dim {
                for c in 0..dim {
                    *out.add(r * dim + c) = m[(r, c)];
                }
            }
            dim as i32
        }
        Ok(Err(e)) => {
            set_text(hh, &format!("{}", e));
            -1
        }
        Err(p2) => {
            let msg = panic_text(p2);
            set_text(hh, &msg);
            -2
        }
    }
}
